<?php
declare(strict_types=1);
namespace App\Controllers;use App\Core\{Csrf,Request,Response,View};use App\Repositories\BackupRepository;use App\Security\Auth;use App\Services\BackupService;use Throwable;
final readonly class BackupController{public function __construct(private View $view,private BackupRepository $repo,private BackupService $service,private Csrf $csrf){}public function index(Request $r):void{$this->allow();$this->view->render('backups/index',['title'=>'Backups','destinations'=>$this->repo->destinations(),'runs'=>$this->repo->runs(),'csrf'=>$this->csrf]);}public function destination(Request $r):void{$this->allow();$this->attempt(fn()=>$this->service->createDestination($r->input));}public function run(Request $r):void{$this->allow();$this->attempt(fn()=>$this->service->request($r->int('destination_id')));}private function attempt(callable $f):never{try{$f();Response::redirect('/backups');}catch(Throwable $e){http_response_code(422);exit(htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8'));}}private function allow():void{if(!Auth::can('settings.manage')){http_response_code(403);exit('Sin permiso');}}}
